	static const uint8_t auThirdPayload[2] = { 0x31U, 0x32U };
	static const uint8_t auFourthPayload[2] = { 0x41U, 0x42U };
	static const uint8_t auFifthPayload[2] = { 0x51U, 0x52U };
	static const uint8_t auSixthPayload[2] = { 0x61U, 0x62U };
