	vAssertTrue(rsrx_channel_manager_get_active_channel(&xSession.xChannelManager) == RSRX_TRANSPORT_CHANNEL_SECONDARY, "retrans channel up holdoff repeated gap stale feedback timeout integration active secondary");

	xTransportEventFrame.eChannelId = RSRX_TRANSPORT_CHANNEL_PRIMARY;
	xTransportEventFrame.eEventType = RSRX_TRANSPORT_EVENT_SEND_COMPLETED;
	vAssertTrue(rsrx_transport_supervisor_process_transport_event(&xSupervisor, &xTransportEventFrame, &pxSupervisorReport) == RSRX_SUPERVISOR_STATUS_IGNORED_EVENT, "retrans channel up holdoff repeated gap stale feedback timeout integration clear first outstanding");

	xTransportEventFrame.eChannelId = RSRX_TRANSPORT_CHANNEL_PRIMARY;
	xTransportEventFrame.eEventType = RSRX_TRANSPORT_EVENT_CHANNEL_UP;
	vAssertTrue(rsrx_transport_supervisor_process_transport_event(&xSupervisor, &xTransportEventFrame, &pxSupervisorReport) == RSRX_SUPERVISOR_STATUS_IGNORED_EVENT, "retrans channel up holdoff repeated gap stale feedback timeout integration first refresh");
	vAssertTrue(rsrx_channel_manager_get_active_channel(&xSession.xChannelManager) == RSRX_TRANSPORT_CHANNEL_SECONDARY, "retrans channel up holdoff repeated gap stale feedback timeout integration hold secondary");

	xTransportEventFrame.eChannelId = RSRX_TRANSPORT_CHANNEL_PRIMARY;
	xTransportEventFrame.eEventType = RSRX_TRANSPORT_EVENT_SEND_FAILED;
	vAssertTrue(rsrx_transport_supervisor_process_transport_event(&xSupervisor, &xTransportEventFrame, &pxSupervisorReport) == RSRX_SUPERVISOR_STATUS_IGNORED_EVENT, "retrans channel up holdoff repeated gap stale feedback timeout integration stale primary feedback");
	vAssertTrue(pxSupervisorReport->eLastDecision == RSRX_SUPERVISOR_DECISION_SEND_FEEDBACK_UNCORRELATED_IGNORED, "retrans channel up holdoff repeated gap stale feedback timeout integration stale feedback decision");
	vAssertTrue(pxSupervisorReport->uConsecutiveSendFailureCount == 0U, "retrans channel up holdoff repeated gap stale feedback timeout integration send budget unchanged");

	axFrames[0].eChannelId = RSRX_TRANSPORT_CHANNEL_SECONDARY;
	axFrames[0].puPayload = auSecondGapFrame;
	axFrames[0].xPayloadLength = xSecondGapLength;
	axFrames[0].eEventType = RSRX_TRANSPORT_EVENT_FRAME_RECEIVED;
	aeStatuses[0] = RSRX_TRANSPORT_STATUS_OK;
