	vAssertTrue(pxSupervisorReport->eLastEffectiveEvent == RSRX_EVENT_SEQUENCE_GAP_DETECTED, "retrans channel up holdoff repeated gap stale feedback timeout integration second gap event");
	vAssertTrue(xTransport.uSendCount == 3U, "retrans channel up holdoff repeated gap stale feedback timeout integration second retrans request sent");

	xTransportEventFrame.eChannelId = RSRX_TRANSPORT_CHANNEL_SECONDARY;
	xTransportEventFrame.eEventType = RSRX_TRANSPORT_EVENT_SEND_COMPLETED;
	vAssertTrue(rsrx_transport_supervisor_process_transport_event(&xSupervisor, &xTransportEventFrame, &pxSupervisorReport) == RSRX_SUPERVISOR_STATUS_IGNORED_EVENT, "retrans channel up holdoff repeated gap stale feedback timeout integration clear second outstanding");
