	vAssertTrue(rsrx_session_get_state(&xSession) == RSRX_STATE_SAFE_DISCONNECT, "retrans channel up holdoff repeated gap stale feedback timeout integration safe disconnect");
	vAssertTrue(pxSupervisorReport->eLastSessionStatus == RSRX_STATUS_REJECTED, "retrans channel up holdoff repeated gap stale feedback timeout integration rejected status");
