	vAssertTrue(xTransport.uSendCount >= 3U, "retrans channel up holdoff repeated gap stale feedback timeout integration cumulative send count");
	vAssertTrue(xApplication.uCallCount == 0U, "retrans channel up holdoff repeated gap stale feedback timeout integration no application callback");
	vAssertTrue(xLifecycleCounter.uCallCount == 1U, "retrans channel up holdoff repeated gap stale feedback timeout integration lifecycle callback");
