	vAssertTrue(rsrx_channel_manager_get_active_channel(&xSession.xChannelManager) == RSRX_TRANSPORT_CHANNEL_SECONDARY, "retrans channel up holdoff repeated gap stale completion unconfirmed integration hold secondary");

	axFrames[0].eChannelId = RSRX_TRANSPORT_CHANNEL_SECONDARY;
	axFrames[0].puPayload = auSecondGapFrame;
	axFrames[0].xPayloadLength = xSecondGapLength;
	axFrames[0].eEventType = RSRX_TRANSPORT_EVENT_FRAME_RECEIVED;
