	vAssertTrue(rsrx_channel_manager_get_active_channel(&xSession.xChannelManager) == RSRX_TRANSPORT_CHANNEL_SECONDARY, "holdoff stale feedback integration active secondary");

	// cppcheck-suppress redundantAssignment
