	vAssertTrue(rsrx_transport_adapter_has_outstanding_send(&xSession.xTransportAdapter) == 1U, "holdoff stale completion soak integration first stale primary outstanding retained");
	vAssertTrue(pxSupervisorReport->uConsecutiveSendFailureCount == 0U, "holdoff stale completion soak integration first stale primary unchanged");

	xTransportEventFrame.eChannelId = RSRX_TRANSPORT_CHANNEL_SECONDARY;
