	uint8_t auDataFrame1[D_RSRX_CODEC_MAX_FRAME_BYTES];
	uint8_t auDataFrame2[D_RSRX_CODEC_MAX_FRAME_BYTES];
	uint8_t auDataFrame3[D_RSRX_CODEC_MAX_FRAME_BYTES];
