	static const uint8_t auInboundDataPayload1[2] = { 0x51U, 0x52U };
	static const uint8_t auInboundDataPayload2[2] = { 0x53U, 0x54U };
	static const uint8_t auInboundDataPayload3[2] = { 0x55U, 0x56U };
