	vAssertTrue(pxSupervisorReport->uConsecutiveSendFailureCount == 1U, "redundancy recovery stale mixed reset integration second primary budget one");
	xTransport.axReceiveFrames[0].eChannelId = RSRX_TRANSPORT_CHANNEL_PRIMARY;
