	static const uint8_t auOutboundPayload[8] = { 0x41U, 0x42U, 0x43U, 0x44U, 0x45U, 0x46U, 0x47U, 0x48U };
	static const uint8_t auPrimaryPayload[2] = { 0x81U, 0x82U };
